package got.network;
import got.GOTBrandingIronItem;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.world.InteractionHand;import net.minecraft.world.item.ItemStack;import net.minecraftforge.network.NetworkEvent;import java.util.function.Supplier;
public record C2SBrandingNamePacket(boolean offhand,String name){public static void encode(C2SBrandingNamePacket p,FriendlyByteBuf b){b.writeBoolean(p.offhand);b.writeUtf(p.name,64);}public static C2SBrandingNamePacket decode(FriendlyByteBuf b){return new C2SBrandingNamePacket(b.readBoolean(),b.readUtf(64));}public static void handle(C2SBrandingNamePacket p,Supplier<NetworkEvent.Context> ctx){ctx.get().enqueueWork(()->{var sp=ctx.get().getSender();if(sp==null)return;ItemStack s=sp.getItemInHand(p.offhand?InteractionHand.OFF_HAND:InteractionHand.MAIN_HAND);if(s.getItem() instanceof GOTBrandingIronItem)GOTBrandingIronItem.setBrand(s,p.name);});ctx.get().setPacketHandled(true);}}
